class TestExpectedMechanicalContract(unittest.TestCase):
    def setUp(self):
        self.data = _read_json(EXPECTED_MECHANICAL_PATH)
        self.excerpt = _nfc(_read_text(EXCERPT_PATH))

    def test_exactly_nine_entries(self):
        self.assertEqual(len(self.data["errors"]), 9)

    def test_every_before_string_occurs_in_excerpt(self):
        for entry in self.data["errors"]:
            before = _nfc(entry["before"])
            self.assertIn(
                before,
                self.excerpt,
                f"{entry['id']}: before string {before!r} does not occur (NFC-normalized) in excerpt.md",
            )

    def test_every_finder_is_mechanical_llm(self):
        for entry in self.data["errors"]:
            self.assertEqual(
                entry["finder"],
                "mechanical-llm",
                f"{entry['id']}: finder must be 'mechanical-llm' per Phase 0 RESULT "
                "(spell-check cannot reach any of these nine)",
            )

    def test_top_level_spellcheck_contribution_is_zero(self):
        self.assertEqual(self.data.get("spellcheckStageContribution"), 0)
        self.assertIn("_note", self.data)
        note = self.data["_note"]
        # The note must actually explain WHY, not just assert zero -- name at least one
        # of the four real-word-wrong-context error strings the Phase 0 RESULT names.
        self.assertTrue(
            any(word in note for word in ("לארוס", "התרי", "למלות", "לאוהב")),
            "the top-level note must explain the zero via the real-word-wrong-context class",
        )

    def test_entries_have_required_keys(self):
        required = {"id", "before", "after", "type", "level", "line", "finder", "rationale"}
        for entry in self.data["errors"]:
            missing = required - set(entry.keys())
            self.assertFalse(missing, f"{entry['id']} missing keys: {missing}")

    def test_ids_are_unique(self):
        ids = [entry["id"] for entry in self.data["errors"]]
        self.assertEqual(len(ids), len(set(ids)))


class TestExpectedEditorialContract(unittest.TestCase):
    def setUp(self):
        self.data = _read_json(EXPECTED_EDITORIAL_PATH)
        self.excerpt_lines = _nfc(_read_text(EXCERPT_PATH)).split("\n")

    def test_marked_as_reconstructed(self):
        self.assertIn("_RECONSTRUCTED_WARNING", self.data)
        warning = self.data["_RECONSTRUCTED_WARNING"]
        self.assertIn("RECONSTRUCTED", warning)
        self.assertIn("editor's own wording", warning.lower())

    def test_exactly_five_categories(self):
        self.assertEqual(len(self.data["categories"]), 5)

    def test_categories_match_plan_phase_1_1(self):
        actual = {c["category"] for c in self.data["categories"]}
        self.assertEqual(actual, EXPECTED_EDITORIAL_CATEGORIES)

    def test_each_category_line_points_at_real_excerpt_line(self):
        for cat in self.data["categories"]:
            line_no = cat["line"]
            self.assertGreaterEqual(line_no, 1)
            self.assertLessEqual(line_no, len(self.excerpt_lines))
            excerpt_line = self.excerpt_lines[line_no - 1]
            # The snippet's first few words should actually appear at (or very near) the
            # cited line -- catches a line number that was guessed rather than grepped.
            first_words = " ".join(cat["snippet"].split()[:4])
            first_words = _nfc(first_words)
            window = "\n".join(self.excerpt_lines[max(0, line_no - 2): line_no + 2])
            self.assertIn(
                first_words,
                window,
                f"{cat['id']}: snippet head {first_words!r} not found near cited line {line_no}",
            )

    def test_ids_are_unique(self):
        ids = [c["id"] for c in self.data["categories"]]
        self.assertEqual(len(ids), len(set(ids)))


