class TestControlParagraphsAreClean(unittest.TestCase):
    """VER-08: the fixture's own negative case. The three clean control paragraphs must
    not contain any of the nine quoted error strings, so a future test that accidentally
    matched against the whole file (rather than just the error paragraphs) would still
    be meaningful."""

    def setUp(self):
        self.excerpt = _nfc(_read_text(EXCERPT_PATH))
        self.mechanical = _read_json(EXPECTED_MECHANICAL_PATH)

    def _control_section_text(self):
        lines = self.excerpt.split("\n")
        start = None
        for i, line in enumerate(lines):
            if "פסקה 15" in line:
                start = i
                break
        self.assertIsNotNone(start, "could not locate the first control paragraph heading")
        return "\n".join(lines[start:])

    def test_exactly_three_control_paragraphs(self):
        control_text = self._control_section_text()
        headings = [l for l in control_text.split("\n") if l.startswith("## ")]
        self.assertEqual(len(headings), 3, "expected exactly three control paragraph headings")

    def test_control_paragraphs_contain_no_error_strings(self):
        control_text = self._control_section_text()
        for entry in self.mechanical["errors"]:
            before = _nfc(entry["before"])
            self.assertNotIn(
                before,
                control_text,
                f"{entry['id']}: error string {before!r} leaked into a control paragraph",
            )


class TestEvalHarnessNodeCheck(unittest.TestCase):
    """node --check must pass on tests/e2e/proofread-recall.mjs even when copied to a
    directory with no ancestor package.json. This repo's own package.json sets
    "type": "module", which would otherwise force strict ESM parsing on a plain .js
    file; copying the harness to an isolated directory with no package.json above it
    proves the file's own syntax (and its .mjs extension, which forces ESM regardless
    of any ancestor package.json) is what makes it parse, not an accident of running
    `node --check` from inside this repo."""

    def test_node_check_passes_in_isolated_directory(self):
        node = _find_node()
        if node is None:
            self.skipTest("node not found on PATH")
        with tempfile.TemporaryDirectory() as tmp_dir:
            # tempfile.mkdtemp() targets the OS temp root, which has no ancestor
            # package.json anywhere above it -- unlike a path still inside this repo.
            isolated_path = os.path.join(tmp_dir, "proofread-recall.mjs")
            with open(HARNESS_PATH, encoding="utf-8") as src:
                content = src.read()
            with open(isolated_path, "w", encoding="utf-8") as dst:
                dst.write(content)
            self.assertFalse(
                os.path.exists(os.path.join(tmp_dir, "package.json")),
                "test setup invariant broken: an ancestor package.json exists",
            )
            result = subprocess.run(
                [node, "--check", isolated_path],
                capture_output=True,
                text=True,
                timeout=30,
            )
            self.assertEqual(
                result.returncode,
                0,
                f"node --check failed on isolated copy:\nstdout={result.stdout}\nstderr={result.stderr}",
            )


def _find_node():
    for candidate in ("node",):
        try:
            found = subprocess.run(
                [sys.executable, "-c", "import shutil,sys; p=shutil.which(sys.argv[1]); print(p or '')", candidate],
                capture_output=True,
                text=True,
                timeout=10,
            )
            path = found.stdout.strip()
            if path:
                return path
        except Exception:
            continue
    return None


